package com.example.foryou.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Represents a record of a medicine intake for a specific day.
 *
 * @property id The unique identifier for the intake record, auto-generated by Room.
 * @property medicineName The name of the medicine that was taken or missed.
 * @property userEmail The email of the user this intake record belongs to.
 * @property date The date of the intake (format: "yyyy-MM-dd").
 * @property taken A boolean flag indicating whether the medicine was taken (true) or missed (false).
 */
@Entity(tableName = "medicine_intake")
data class MedicineIntake(
    @PrimaryKey(autoGenerate = true) val id: Int = 0,
    val medicineName: String,
    val userEmail: String,
    val date: String, // yyyy-MM-dd
    val taken: Boolean // true = taken, false = not taken
)
